import { AsyncPipe, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DoCheck,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostBinding,
  inject,
  Injector,
  Input,
  numberAttribute,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  FormsModule,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import { dropdownAnimations } from '@questrade/allspark-angular-components/core/animations';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  DOWN_ARROW,
  ENTER,
  ErrorState,
  nGramScore,
  UP_ARROW,
  voidFn,
} from '@questrade/allspark-angular-components/core/utils';
import {
  QDropmenuComponent,
  QDropmenuDensity,
  QDropmenuLoadingVariant,
  QDropmenuOption,
  QDropmenuOriginDirective,
  QDropmenuSelectionChange,
} from '@questrade/allspark-angular-components/dropmenu';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import {
  QInputDirective,
  QInputGroupComponent,
} from '@questrade/allspark-angular-components/input';
import { check, dropArrowDown, dropArrowUp } from '@questrade/allspark-icons/icons';
import { BehaviorSubject, debounceTime, Observable, takeUntil } from 'rxjs';
import { QDropdownOption } from './types/dropdown-option.interface';
import { QDropdownWidth } from './types/dropdown-width.type';

let nextUniqueId = 0;

@Component({
  selector: 'q-dropdown',
  templateUrl: './dropdown.component.html',
  styleUrls: ['./dropdown.component.scss'],
  animations: [dropdownAnimations.triggerRotate],
  imports: [
    AsyncPipe,
    NgIf,
    NgTemplateOutlet,
    FormsModule,
    QIconComponent,
    QDropmenuComponent,
    QInputDirective,
    QInputGroupComponent,
    QDropmenuOriginDirective,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QDropdownComponent),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QDropdownComponent },
    QDestroyService,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QDropdownComponent<T>
  extends ErrorState
  implements OnInit, ControlValueAccessor, FormFieldControl, DoCheck, OnChanges
{
  private injector = inject<Injector>(Injector);

  @Output() readonly valueChange = new EventEmitter<QDropdownOption<T>>();
  @Output() readonly inputChange = new EventEmitter<string>();
  @Output() readonly inputFocus = new EventEmitter<FocusEvent>();
  @Output() readonly inputBlur = new EventEmitter<FocusEvent>();

  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input() controlId = `q-dropdown-${nextUniqueId++}`;
  @Input() loadingVariant: QDropmenuLoadingVariant = 'spinner';
  @Input() loadingSkeletonTemplate: TemplateRef<unknown> | null = null;
  @Input() placeholder = '';
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input({ transform: booleanAttribute }) customSearch = false;
  @Input({ transform: booleanAttribute }) searchCaseSensitive = false;
  @Input({ transform: numberAttribute }) searchResultsSize = 10;
  @Input({ transform: numberAttribute }) searchDebounce = 0;
  @Input({ transform: numberAttribute }) searchGramSize = 2;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-dropdown-searchable') searchable =
    true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-dropdown';
  @Input() dropmenuWidth: QDropdownWidth = 'full';
  @Input() dropmenuDensity: QDropmenuDensity = 'default';
  @Input() dropmenuFooterMessage = '';
  @Input() dropmenuFooterTemplate: TemplateRef<unknown> | null = null;
  @Input() dropmenuEmptyStateTemplate: TemplateRef<unknown> | null = null;
  @Input() dropmenuOptionTemplate: TemplateRef<unknown> | null = null;
  @Input() groupLabelTemplate: TemplateRef<unknown> | null = null;
  @Input() groupBy: string | ((option: QDropmenuOption<T>) => unknown) | null = null;
  @Input() groupLabel:
    | string
    | ((groupKey: unknown, options: QDropmenuOption<T>[]) => string | null)
    | Record<string, string>
    | null = null;

  @Input() get options(): QDropdownOption<T>[] {
    return this._filteredOptions ?? this._options;
  }
  set options(value: QDropdownOption<T>[]) {
    this._options = value;
    this._selectedOption = this._findSelectedOption();
    this._triggerValue = this._selectedOption?.label || '';
    this._inputValue = this._selectedOption?.label ?? '';
  }

  @Input() get hasError(): boolean {
    return this._hasError || this.errorState;
  }
  set hasError(value: boolean) {
    this._hasError = value;
    this.stateChanges.next();
  }

  @Input() get value(): T {
    return this._value;
  }
  set value(value: T) {
    this._value = value;
    this._selectedOption = this._findSelectedOption();
    this._triggerValue = this._selectedOption?.label || '';
    this._inputValue = this._selectedOption?.label ?? '';
    this._cdr.markForCheck();
  }

  @ViewChild('button') _buttonRef!: ElementRef<HTMLElement>;
  @ViewChild('input') _inputRef!: ElementRef<HTMLElement>;
  @ViewChild(QDropmenuComponent, { static: true }) _dropmenuRef!: QDropmenuComponent<T>;

  @HostBinding('class') _hostClass = 'q-dropdown';

  _selectedOption: QDropdownOption<T> | null = null;
  _searchStringObservable$: Observable<string> | null = null;
  _inputValue = '';
  _hasError = false;
  _triggerValue = '';

  private _onChange: (_: T) => void = voidFn;
  private _onTouch: () => void = voidFn;
  private _options: QDropdownOption<T>[] = [];
  private _searchString$ = new BehaviorSubject('');
  private _filteredOptions: QDropdownOption<T>[] | null = null;
  private _value!: T;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));

    this.stateChanges.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._cdr.markForCheck();
    });

    this._searchStringObservable$ = this._searchString$.asObservable();

    this._iconRegistry.registerIcons([check, dropArrowDown, dropArrowUp]);
  }

  ngOnInit(): void {
    this.setComponentControl();

    this._searchString$
      .pipe(debounceTime(this.searchDebounce), takeUntil(this._destroy$))
      .subscribe(this._onSearchStringUpdate.bind(this));

    if (this.searchable) {
      this._dropmenuRef._withTypeahead = false;
      this._dropmenuRef._selectKeys = [ENTER];
    }
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { disabled, readonly } = changes;

    if ((disabled || readonly) && this.isDropdownOpened) {
      this._toggle();
    }
  }

  _onValueChanged(event: QDropmenuOption<T> | QDropmenuOption<T>[]): void {
    this.valueChange.emit(event as QDropdownOption<T>);
  }

  _onDropmenuSelection({ option }: QDropmenuSelectionChange<T>): void {
    const selectedValue = option.value;

    if (!selectedValue) return;

    this.value = selectedValue;
    this._triggerValue = option.label;
    this._searchString$.next('');
    this._onChange(this.value);
  }

  _onInputChange(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this._searchString$.next(value);

    if (this._dropmenuRef) {
      this._dropmenuRef._getDropmenuHostElement().scrollTop = 8;
    }

    this.inputChange.emit(value);

    if (!this._dropmenuRef.isOpened && !this.readonly) {
      this._dropmenuRef.open();
    }
  }

  _onInputBlur(event: FocusEvent): void {
    const value = (event.target as HTMLInputElement).value;

    if ((!value || !this._dropmenuRef.options.length) && this._selectedOption) {
      this._inputValue = this._selectedOption.label;
      this._searchString$.next('');
    }
    this.inputBlur.emit(event);
  }

  _onInputFocus(event: FocusEvent): void {
    this.inputFocus.emit(event);
  }

  _onArrowIconClick(): void {
    if (this.searchable && !this.disabled && !this.readonly) {
      this._toggle();
    }
  }

  _onInputClick(): void {
    if (!this.disabled && !this.readonly && !this._dropmenuRef.isOpened) {
      this._dropmenuRef.open();
    }
  }

  _onButtonTriggerClick(): void {
    if (this.disabled || this.readonly || this._dropmenuRef.isOpened) return;
    this._dropmenuRef.open();
  }

  _onButtonTriggerKeydown(event: KeyboardEvent): void {
    if (this.disabled || this.readonly) return;

    if ([DOWN_ARROW, UP_ARROW].includes(event.code) && !this._dropmenuRef.isOpened) {
      event.stopPropagation();
      this._dropmenuRef.open();
    }
  }

  _onInputTriggerKeyDown(event: KeyboardEvent): void {
    if (this.disabled || this.readonly) return;

    if ([DOWN_ARROW, UP_ARROW, ENTER].includes(event.code) && !this._dropmenuRef.isOpened) {
      event.stopPropagation();
      this._dropmenuRef.open();
    }
  }

  _onDropmenuClose(): void {
    this._onTouch();
  }

  /** @hidden */
  writeValue(value: T): void {
    this.value = value;
  }

  /** @hidden */
  registerOnChange(fn: (_: T) => void): void {
    this._onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouch = fn;
  }

  /** @hidden */
  setDisabledState(disabled: boolean): void {
    this.disabled = disabled;
    this._cdr.markForCheck();
  }

  get isDropdownOpened(): boolean {
    return !!this._dropmenuRef?.isOpened;
  }

  private setComponentControl(): void {
    const injectedControl = this.injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }

  private _toggle(): void {
    if (this.isDropdownOpened) {
      this._dropmenuRef.close();
    } else {
      this._dropmenuRef.open();
    }
  }

  private _findSelectedOption(): QDropdownOption<T> | null {
    return this._options?.find((option) => option.value === this.value) ?? null;
  }

  private _onSearchStringUpdate(value: string): void {
    if (value === '' || this.customSearch) {
      this._filteredOptions = null;
    } else {
      this._filteredOptions = [...this._options]
        .filter(
          (option) =>
            !option.disabled &&
            nGramScore(option.label, value, this.searchCaseSensitive, this.searchGramSize) > 0,
        )
        .sort(
          (a, b) =>
            nGramScore(b.label, value, this.searchCaseSensitive, this.searchGramSize) -
            nGramScore(a.label, value, this.searchCaseSensitive, this.searchGramSize),
        )
        .slice(0, this.searchResultsSize);
    }
    this._cdr.markForCheck();
  }
}
